package com.example.internmanagement.controller;
import com.example.internmanagement.dao.NotificationDAO;import com.example.internmanagement.model.User;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.SQLException;
@WebServlet("/notifications") public class NotificationServlet extends HttpServlet{private final NotificationDAO dao=new NotificationDAO();@Override protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;}try{req.setAttribute("notifications",dao.findRecent(u.getId(),100));req.getRequestDispatcher("/WEB-INF/views/notifications.jsp").forward(req,resp);}catch(SQLException e){throw new ServletException("Không thể tải thông báo.",e);}}@Override protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;}try{dao.markAllRead(u.getId());}catch(SQLException ignored){}resp.sendRedirect(req.getContextPath()+"/notifications");}}
